{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a close structural analog sharing the dimethoxy-tetrahydroisoquinoline core, has an absolute oral bioavailability of approximately 49% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Donepezil, which shares the dimethoxyaromatic and basic amine/cyclic carbonyl motif, has an oral bioavailability of 100% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Noscapine, an isoquinoline alkaloid with a dimethoxyisoquinoline and N-methyl tetrahydroisoquinoline, has a mean absolute oral bioavailability of 30% (range 16-58%) in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Verapamil, sharing dimethoxyphenyl and tertiary amine features, has an absolute oral bioavailability of 34% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, a structurally related dimethoxybenzoquinolizine, has very low oral bioavailability (mean 4.9%) in patients, but this is attributed to extensive first-pass metabolism of its ketone, a liability not present in the query's lactam/basic side chain; this is contradictory evidence with limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C72"],
      "claim": "Almorexant, a dimethoxy-tetrahydroisoquinoline amide, has an absolute oral bioavailability of 11.4% in humans, but it lacks the basic tertiary amine of the query and has a higher molecular weight, limiting transferability; contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) based on multiple structurally related analogs with moderate-to-high oral bioavailability (donepezil ~100%, valbenazine ~49%, noscapine ~30%, verapamil ~20-35%), outweighing low-F analogs (tetrabenazine, almorexant) that have specific metabolic/physicochemical liabilities not shared by the query.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "Uncertainty in whether the lactam and flexible tertiary amine side chain confer metabolic stability similar to donepezil/valbenazine or first-pass liability similar to tetrabenazine/almorexant.",
    "Low neutral fraction (0.02) and high rotatable bond count (10) may reduce absorption, but no experimental permeability data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

